const listActorInputRecords = `-- name: ListActorInputRecords :many
SELECT id, environment_id, actor_id, direction, sequence, data, content_type, source_kind, source_run_id, producer_run_id, producer_attempt_number, claim_id, created_at
  FROM actor_records
 WHERE actor_id = $1
   AND direction = 'input'
   AND sequence > $2
 ORDER BY sequence, id
 LIMIT $3
`

type ListActorInputRecordsParams struct {
	ActorID       pgtype.UUID `json:"actor_id"`
	AfterSequence int64       `json:"after_sequence"`
	LimitCount    int32       `json:"limit_count"`
}

func (q *Queries) ListActorInputRecords(ctx context.Context, arg ListActorInputRecordsParams) ([]ActorRecord, error) {
	rows, err := q.db.Query(ctx, listActorInputRecords, arg.ActorID, arg.AfterSequence, arg.LimitCount)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ActorRecord
	for rows.Next() {
		var i ActorRecord
		if err := rows.Scan(
			&i.ID,
			&i.EnvironmentID,
			&i.ActorID,
			&i.Direction,
			&i.Sequence,
			&i.Data,
			&i.ContentType,
			&i.SourceKind,
			&i.SourceRunID,
			&i.ProducerRunID,
			&i.ProducerAttemptNumber,
			&i.ClaimID,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

